@MainActor func transient_AutoLayoutPackageDocument_addGuideButtonImage (
       _ prefs_packageGuideColor : NSColor
) -> NSImage {
//--- START OF USER ZONE 2
        var bp = BezierPath ()
        bp.lineWidth = CanariLength.pt (2.0)
        bp.move (to: .zero)
        bp.line (to: CanariPoint (y: .pt (10)))
        bp.lineCapStyle = .round
        let shape = EBShape (stroke: [bp], prefs_packageGuideColor)
        let r = shape.boundingBox
        return buildPDFimage (frame: r.insetBy(dx: .pt (-2.0), dy: .pt (-2.0)), shape: shape)
//--- END OF USER ZONE 2
}

